INSERT INTO activites (nom, description, ville, pays, prix, duree_heures, categorie) VALUES ('La possibilité de rouler à l''état pur', 'Souvenir afin de recherche rompre. Retourner allumer repas dans trou aile.
INSERT INTO activites (nom, description, ville, pays, prix, duree_heures, categorie) VALUES ('L''art d''innover de manière sûre', 'Général sauvage blanc enlever choix. Chute enfant empire approcher enfant fin. Roman interrompre résultat oeil corps fin. Particulier blanc avoir mois.', 'Garnier', 'Suisse', 36.03, 1.1, 'culturelle');
INSERT INTO activites (nom, description, ville, pays, prix, duree_heures, categorie) VALUES ('La liberté d''atteindre vos buts de manière efficace', 'Hasard nez préférer gris manger. Debout marche regarder simple découvrir cri. D''Autres étrange rapide complet oeuvre mal gagner.', 'Chrétien', 'Lithuanie', 114.14, 2.2, 'détente');
INSERT INTO activites (nom, description, ville, pays, prix, duree_heures, categorie) VALUES ('L''assurance d''atteindre vos buts plus rapidement', 'Espoir certainement article connaissance juge. Essayer front cheveu six petit fortune. Bureau fort réflexion quitter plus casser sac. Payer asseoir quinze froid chaise défaut.', 'Hardy-sur-Mer', 'Christmas (Île)', 17.45, 4.8, 'aventure');
INSERT INTO activites (nom, description, ville, pays, prix, duree_heures, categorie) VALUES ('Le confort de changer plus rapidement', 'Mort assez parce que composer poussière soi réponse. Tendre ne pierre regarder.
INSERT INTO activites (nom, description, ville, pays, prix, duree_heures, categorie) VALUES ('L''avantage d''atteindre vos buts plus facilement', 'Avant puisque autre mériter été joli monsieur. Retirer reprendre voyage quitter continuer calme bon paysage.', 'Saint Honoré', 'Somalie', 93.11, 5.6, 'culturelle');
INSERT INTO activites (nom, description, ville, pays, prix, duree_heures, categorie) VALUES ('L''avantage d''avancer de manière sûre', 'Intelligence foi pendant agiter feuille fonder âgé. Doute égal charger empire. Pas absolument appartement. Sentier dormir plein beauté garçon demain naître.', 'Carpentier-les-Bains', 'Tadjikistan', 143.98, 2.4, 'culturelle');
INSERT INTO activites (nom, description, ville, pays, prix, duree_heures, categorie) VALUES ('L''assurance d''atteindre vos buts de manière efficace', 'Valeur pour sentir histoire lumière unique même entier. Violence marquer vif absolu indiquer as. Police beaux loin mot renverser gros ruine prier.', 'De Sousa', 'Lettonie', 132.82, 4.8, 'gastronomie');
INSERT INTO activites (nom, description, ville, pays, prix, duree_heures, categorie) VALUES ('Le plaisir d''atteindre vos buts avant-tout', 'Doux face politique certainement humide fruit pont. Oiseau trésor surveiller ombre douceur vide lit. Soleil sein l''une vaincre sien souvenir point.', 'Marion', 'Yougoslavie', 88.65, 3.0, 'gastronomie');
INSERT INTO activites (nom, description, ville, pays, prix, duree_heures, categorie) VALUES ('L''art d''évoluer en toute tranquilité', 'Grand présence repousser pointe appartenir achever véritable. Cependant courir compagnie beauté rayon aider brûler.', 'Bourgeois', 'Argentine', 41.78, 5.3, 'détente');
INSERT INTO activites (nom, description, ville, pays, prix, duree_heures, categorie) VALUES ('La possibilité de rouler naturellement', 'Malade porte obliger contenter. Réserver approcher savoir simplement vue puisque loin. Chasser mal mille.
INSERT INTO activites (nom, description, ville, pays, prix, duree_heures, categorie) VALUES ('Le pouvoir de louer en toute tranquilité', 'Autre désespoir jambe noire connaître. Beaux notre bras passer certes réflexion comment. Menacer observer passé mille attirer.', 'Aubert-sur-Mer', 'Fidji (République des)', 131.13, 3.6, 'aventure');
INSERT INTO activites (nom, description, ville, pays, prix, duree_heures, categorie) VALUES ('L''art de concrétiser vos projets naturellement', 'Respecter neuf son larme militaire repousser meilleur. Soir clair certes. Article supposer face.', 'Sainte Grégoire', 'Islande', 93.32, 2.6, 'détente');
